+import type { ItemSchema, MapSchema } from '~/schema/index.js'
+import { isObject } from '~/utils/validation/isObject.js'
+
+type ObjectSchema = ItemSchema | MapSchema
+
+export const requiredIfConditions = (schema: ObjectSchema, value: unknown, existingNames: Record<string, string> = {}) => {
+  const ExpressionAttributeNames: Record<string, string> = {}
+  const conditions: string[] = []
+  let cursor = 1
+  const token = (name: string): string => {
+    let candidate = `#r_${cursor++}`
+    while (candidate in existingNames || candidate in ExpressionAttributeNames) candidate = `#r_${cursor++}`
+    ExpressionAttributeNames[candidate] = name
+    return candidate
+  }
+  const visit = (currentSchema: ObjectSchema, currentValue: unknown, path: string[]): void => {
+    if (!isObject(currentValue)) return
+    for (const [attributeName, attribute] of Object.entries(currentSchema.attributes)) {
+      const attributeValue = currentValue[attributeName]
+      for (const requirement of attribute.props.requiredIf ?? []) {
+        if (attributeValue === undefined && requirement.values.some(v => Object.is(v, currentValue[requirement.attributeName]))) {
+          const savedPath = [...path, attribute.props.savedAs ?? attributeName]
+          conditions.push(`attribute_exists(${savedPath.map(token).join('.')})`)
+        }
+      }
+      if ((attribute.type === 'map' || attribute.type === 'item') && attributeValue !== undefined) {
+        visit(attribute, attributeValue, [...path, attribute.props.savedAs ?? attributeName])
+      }
+    }
+  }
+  visit(schema, value, [])
+  return { ...(conditions.length > 0 ? { ConditionExpression: conditions.join(' AND ') } : {}), ExpressionAttributeNames }
+}
